package container

import (
	"strings"
)

// entrypointScript runs as the sandbox user before the shell or command.
//
// It refreshes Rig-managed files in $HOME when the image changes. That matters
// when home is a fresh tmpfs (read-only images) or a volume that outlives the
// image (persistent read-only images). It also moves MCP server secrets out of
// the environment into private files the tool-call guard reads, so they are
// not inherited by every process the agent starts.
const entrypointScript = `#!/bin/sh
# Rig sandbox entrypoint. Generated by rig; rebuilt with the image.
RIG_DIR=/etc/rig

if [ -w "$HOME" ] && ! cmp -s "$RIG_DIR/version" "$HOME/.rig-version" 2>/dev/null; then
  cp -a "$RIG_DIR/skel/." "$HOME/" 2>/dev/null || true
  if [ -f "$RIG_DIR/claude-mcp.json" ]; then
    if [ -s "$HOME/.claude.json" ] && \
       jq -s '.[0] + {mcpServers: .[1].mcpServers}' "$HOME/.claude.json" "$RIG_DIR/claude-mcp.json" > "$HOME/.claude.json.rig" 2>/dev/null; then
      mv "$HOME/.claude.json.rig" "$HOME/.claude.json"
    else
      rm -f "$HOME/.claude.json.rig"
      cp "$RIG_DIR/claude-mcp.json" "$HOME/.claude.json"
    fi
  fi
  cp "$RIG_DIR/version" "$HOME/.rig-version" 2>/dev/null || true
fi
mkdir -p "$HOME/workspace" "$HOME/.rig" 2>/dev/null || true

if env | grep -q '^RIG_MCP_'; then
  rm -rf "$HOME/.rig/mcp-env"
  (umask 077 && mkdir -p "$HOME/.rig/mcp-env")
  env | grep '^RIG_MCP_' | while IFS='=' read -r key value; do
    rest=${key#RIG_MCP_}
    idx=${rest%%_*}
    name=${rest#*_}
    (umask 077 && printf '%s=%s\n' "$name" "$value" >> "$HOME/.rig/mcp-env/$idx.env")
  done
  for key in $(env | grep '^RIG_MCP_' | cut -d= -f1); do
    unset "$key"
  done
fi

exec "$@"
`

// bashrc renders the sandbox user's shell profile.
func bashrc(profileName, level string, agentNames []string) string {
	lines := []string{
		"# Rig sandbox shell. Generated by rig; rebuilt with the image.",
		`export PS1='\[\033[1;35m\]rig\[\033[0m\]:\[\033[1;34m\]\w\[\033[0m\]\$ '`,
		`export PATH="$HOME/.local/bin:$PATH"`,
		`alias ll='ls -alF --color=auto'`,
		`alias la='ls -A --color=auto'`,
		``,
		`if [ -z "$RIG_GREETED" ]; then`,
		`    export RIG_GREETED=1`,
		`    echo ""`,
		`    echo -e "  \033[1;35mRig sandbox\033[0m ` + shellSafe(profileName) + ` \033[2m(security: ` + shellSafe(level) + `)\033[0m"`,
	}
	for _, name := range agentNames {
		lines = append(lines, `    echo -e "  \033[0;36m*\033[0m `+shellSafe(name)+`"`)
	}
	lines = append(lines, `    echo ""`, `fi`, ``)
	return strings.Join(lines, "\n")
}

// shellSafe keeps only characters that need no quoting inside a double-quoted
// echo. Profile names and levels are already validated; this is belt and braces.
func shellSafe(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch {
		case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9', r == '-', r == '_', r == ' ', r == '.', r == '(', r == ')':
			b.WriteRune(r)
		}
	}
	return b.String()
}
